function withTotal(cart, total) {
  cart.total = total;
  return cart;
}

function withItem(items, item) {
  items.push(item);
  return items;
}

function markDone(item) {
  item.done = true;
  return item;
}

items.solution:
function toggleItemDone(items, id) {
  return items.map((item) =>
    item.id === id ? { ...item, done: !item.done } : item,
  );
}

function updateItemQty(items, id, qty) {
  return items.map((item) => (item.id === id ? { ...item, qty } : item));
}

function updateItemPrice(cart, id, price) {
  return {
    ...cart,
    items: cart.items.map((item) =>
      item.id === id ? { ...item, price } : item,
    ),
  };
}
